import React, { useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  Settings, Users, UserPlus, Copy, Check, Shield,
  Globe, Bell, Lock, ChevronRight, Sparkles, Mail,
  Crown, Eye, User
} from "lucide-react";
import { useWorkspace } from "../context/WorkspaceContext";
import { useAuth } from "../context/AuthContext";
import { Avatar } from "../components/layout/Sidebar";

const ICONS = ["🏢", "🚀", "⚡", "🎯", "🛠️", "🌟", "🔥", "💡", "🎨", "📦"];
const COLORS = [
  "#6366f1", "#8b5cf6", "#ec4899", "#14b8a6",
  "#f97316", "#eab308", "#22c55e", "#3b82f6",
];

const ROLE_META = {
  owner: { icon: Crown, color: "#f59e0b", bg: "rgba(245,158,11,0.12)", label: "Owner" },
  admin: { icon: Shield, color: "#8b5cf6", bg: "rgba(139,92,246,0.12)", label: "Admin" },
  member: { icon: User, color: "#64748b", bg: "rgba(100,116,139,0.12)", label: "Member" },
  viewer: { icon: Eye, color: "#06b6d4", bg: "rgba(6,182,212,0.12)", label: "Viewer" },
};

/* ── Sidebar nav item ─────────────────────────────────────────── */
const NavItem = ({ id, label, icon: Icon, active, onClick, badge }) => (
  <button
    onClick={() => onClick(id)}
    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium
      transition-all duration-200 group relative overflow-hidden
      ${active
        ? "text-white"
        : "text-slate-400 hover:text-slate-200 hover:bg-white/5"
      }`}
    style={active ? {
      background: "linear-gradient(135deg,rgba(124,58,237,0.25),rgba(79,70,229,0.15))",
      boxShadow: "inset 0 0 0 1px rgba(124,58,237,0.3)",
    } : {}}
  >
    {active && (
      <span
        className="absolute left-0 top-1/2 -translate-y-1/2 w-0.5 h-5 rounded-r-full"
        style={{ background: "linear-gradient(180deg,#a78bfa,#6366f1)" }}
      />
    )}
    <span
      className="w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 transition-all duration-200"
      style={{
        background: active
          ? "linear-gradient(135deg,rgba(124,58,237,0.35),rgba(79,70,229,0.25))"
          : "rgba(255,255,255,0.04)",
      }}
    >
      <Icon size={15} className={active ? "text-violet-300" : "text-slate-500 group-hover:text-slate-300"} />
    </span>
    <span className="flex-1 text-left">{label}</span>
    {badge != null && (
      <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-slate-700/60 text-slate-400">
        {badge}
      </span>
    )}
    {active && <ChevronRight size={13} className="text-violet-400 flex-shrink-0" />}
  </button>
);

/* ── Section header ───────────────────────────────────────────── */
const SectionHeader = ({ icon: Icon, title, subtitle, color = "#8b5cf6" }) => (
  <div className="flex items-center gap-4 mb-8">
    <div
      className="w-11 h-11 rounded-2xl flex items-center justify-center flex-shrink-0"
      style={{
        background: `linear-gradient(135deg,${color}30,${color}15)`,
        boxShadow: `0 0 0 1px ${color}30, 0 8px 24px ${color}20`,
      }}
    >
      <Icon size={18} style={{ color }} />
    </div>
    <div>
      <h2 className="text-lg font-bold text-white">{title}</h2>
      {subtitle && <p className="text-sm text-slate-500 mt-0.5">{subtitle}</p>}
    </div>
  </div>
);

/* ── Field wrapper ────────────────────────────────────────────── */
const Field = ({ label, hint, children }) => (
  <div className="space-y-2">
    <div className="flex items-center justify-between">
      <label className="text-sm font-semibold text-slate-300">{label}</label>
      {hint && <span className="text-xs text-slate-600">{hint}</span>}
    </div>
    {children}
  </div>
);

/* ══════════════════════════════════════════════════════════════════
   MAIN COMPONENT
══════════════════════════════════════════════════════════════════ */
const WorkspaceSettings = () => {
  const { workspaceId } = useParams();
  const navigate = useNavigate();
  const { activeWorkspace, updateWorkspace, inviteMember } = useWorkspace();
  const { user } = useAuth();

  const [activeTab, setActiveTab] = useState("general");
  const [form, setForm] = useState({
    name: activeWorkspace?.name || "",
    description: activeWorkspace?.description || "",
    icon: activeWorkspace?.icon || "🏢",
    color: activeWorkspace?.color || "#6366f1",
  });
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [saveError, setSaveError] = useState("");

  const [inviteEmail, setInviteEmail] = useState("");
  const [inviteRole, setInviteRole] = useState("member");
  const [inviting, setInviting] = useState(false);
  const [inviteResult, setInviteResult] = useState(null);
  const [copiedLink, setCopiedLink] = useState(false);

  const userRole = activeWorkspace?.members?.find(m => m.user?._id === user?._id)?.role;
  const canEdit = ["owner", "admin"].includes(userRole);
  const memberCount = activeWorkspace?.members?.length || 0;

  const handleSave = async (e) => {
    e.preventDefault();
    if (!form.name.trim()) return;
    setSaving(true); setSaveError("");
    const result = await updateWorkspace(workspaceId || activeWorkspace?._id, form);
    setSaving(false);
    if (result.success) { setSaved(true); setTimeout(() => setSaved(false), 2500); }
    else setSaveError(result.message);
  };

  const handleInvite = async (e) => {
    e.preventDefault();
    if (!inviteEmail) return;
    setInviting(true); setInviteResult(null);
    const result = await inviteMember(workspaceId || activeWorkspace?._id, inviteEmail, inviteRole);
    setInviting(false); setInviteResult(result);
    if (result.success) setInviteEmail("");
  };

  const copyLink = () => {
    if (inviteResult?.invite?.inviteLink) {
      navigator.clipboard.writeText(inviteResult.invite.inviteLink);
      setCopiedLink(true); setTimeout(() => setCopiedLink(false), 2000);
    }
  };

  if (!activeWorkspace) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-center space-y-3">
          <div className="w-16 h-16 rounded-2xl bg-slate-800/60 flex items-center justify-center mx-auto text-3xl">🏢</div>
          <p className="text-slate-400 font-medium">Select a workspace first</p>
        </div>
      </div>
    );
  }

  const navItems = [
    { id: "general", label: "General", icon: Settings, },
    { id: "members", label: "Members", icon: Users, badge: memberCount },
    ...(canEdit ? [{ id: "invite", label: "Invite People", icon: UserPlus }] : []),
  ];

  return (
    <div className="flex h-full overflow-hidden" style={{ background: "var(--color-bg)" }}>

      {/* ── Left settings sidebar ─────────────────────────────── */}
      <aside
        className="w-64 flex-shrink-0 flex flex-col border-r overflow-y-auto"
        style={{
          borderColor: "rgba(255,255,255,0.05)",
          background: "rgba(15,23,42,0.50)",
        }}
      >
        {/* Workspace identity card */}
        <div className="p-5 border-b" style={{ borderColor: "rgba(255,255,255,0.05)" }}>
          <div
            className="relative rounded-2xl p-4 overflow-hidden"
            style={{
              background: `linear-gradient(135deg, ${form.color}20, ${form.color}08)`,
              border: `1px solid ${form.color}25`,
            }}
          >
            {/* Glow orb */}
            <div
              className="absolute -top-6 -right-6 w-24 h-24 rounded-full opacity-30 blur-2xl pointer-events-none"
              style={{ background: form.color }}
            />
            <div className="relative flex items-center gap-3">
              <div
                className="w-12 h-12 rounded-xl flex items-center justify-center text-2xl flex-shrink-0 shadow-lg"
                style={{
                  background: `linear-gradient(135deg, ${form.color}, ${form.color}99)`,
                  boxShadow: `0 8px 24px ${form.color}50`,
                }}
              >
                {form.icon}
              </div>
              <div className="min-w-0">
                <p className="font-bold text-white text-sm truncate">{form.name || activeWorkspace.name}</p>
                <p className="text-xs text-slate-500 mt-0.5">Workspace</p>
              </div>
            </div>
          </div>
        </div>

        {/* Nav */}
        <nav className="flex-1 p-3 space-y-1">
          <p className="text-[10px] font-bold uppercase tracking-widest text-slate-600 px-4 pb-2 pt-1">
            Settings
          </p>
          {navItems.map(item => (
            <NavItem
              key={item.id}
              {...item}
              active={activeTab === item.id}
              onClick={setActiveTab}
            />
          ))}
        </nav>

        {/* Footer hint */}
        <div className="p-4 mx-3 mb-3 rounded-xl" style={{ background: "rgba(124,58,237,0.08)", border: "1px solid rgba(124,58,237,0.15)" }}>
          <div className="flex items-start gap-2.5">
            <Sparkles size={13} className="text-violet-400 mt-0.5 flex-shrink-0" />
            <p className="text-xs text-slate-500 leading-relaxed">
              Changes apply to all members of this workspace.
            </p>
          </div>
        </div>
      </aside>

      {/* ── Main content ──────────────────────────────────────── */}
      <main className="flex-1 overflow-y-auto">
        <div className="max-w-2xl mx-auto px-8 py-8">

          {/* ── GENERAL TAB ─────────────────────────────────── */}
          {activeTab === "general" && (
            <div className="animate-fade-in space-y-6">
              <SectionHeader
                icon={Settings}
                title="General Settings"
                subtitle="Customize your workspace name, identity and appearance."
                color="#8b5cf6"
              />

              {saveError && (
                <div className="px-4 py-3 rounded-xl flex items-center gap-2.5 text-sm animate-fade-in"
                  style={{ background: "rgba(239,68,68,0.08)", border: "1px solid rgba(239,68,68,0.2)" }}>
                  <span className="w-1.5 h-1.5 rounded-full bg-red-400 flex-shrink-0" />
                  <span className="text-red-400">{saveError}</span>
                </div>
              )}

              <form onSubmit={handleSave} className="space-y-6">
                {/* Name */}
                <div
                  className="rounded-2xl p-6 space-y-5"
                  style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.06)" }}
                >
                  <Field label="Workspace Name" hint="Required">
                    <input
                      value={form.name}
                      onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
                      disabled={!canEdit}
                      className="input-field disabled:opacity-50 disabled:cursor-not-allowed"
                      placeholder="My Workspace"
                    />
                  </Field>

                  <Field label="Description" hint="Optional">
                    <textarea
                      value={form.description}
                      onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
                      disabled={!canEdit}
                      rows={3}
                      className="input-field resize-none disabled:opacity-50 disabled:cursor-not-allowed"
                      placeholder="What does this workspace track?"
                    />
                  </Field>
                </div>

                {/* Icon + Color */}
                <div
                  className="rounded-2xl p-6"
                  style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.06)" }}
                >
                  <p className="text-sm font-bold text-slate-300 mb-4">Appearance</p>
                  <div className="grid grid-cols-2 gap-6">
                    <Field label="Icon">
                      <div className="flex flex-wrap gap-2 mt-1">
                        {ICONS.map(icon => (
                          <button
                            key={icon}
                            type="button"
                            onClick={() => canEdit && setForm(f => ({ ...f, icon }))}
                            className="w-10 h-10 rounded-xl text-xl transition-all duration-150 flex items-center justify-center"
                            style={{
                              background: form.icon === icon
                                ? `linear-gradient(135deg,${form.color}40,${form.color}20)`
                                : "rgba(255,255,255,0.04)",
                              border: form.icon === icon
                                ? `1.5px solid ${form.color}60`
                                : "1.5px solid rgba(255,255,255,0.06)",
                              transform: form.icon === icon ? "scale(1.12)" : "scale(1)",
                              cursor: canEdit ? "pointer" : "not-allowed",
                              opacity: !canEdit ? 0.5 : 1,
                            }}
                          >
                            {icon}
                          </button>
                        ))}
                      </div>
                    </Field>

                    <Field label="Color">
                      <div className="flex flex-wrap gap-2.5 mt-1">
                        {COLORS.map(color => (
                          <button
                            key={color}
                            type="button"
                            onClick={() => canEdit && setForm(f => ({ ...f, color }))}
                            className="w-9 h-9 rounded-full transition-all duration-150 flex-shrink-0"
                            style={{
                              background: color,
                              cursor: canEdit ? "pointer" : "not-allowed",
                              opacity: !canEdit ? 0.5 : 1,
                              transform: form.color === color ? "scale(1.2)" : "scale(1)",
                              boxShadow: form.color === color
                                ? `0 0 0 2px rgba(255,255,255,0.15), 0 0 0 4px ${color}60, 0 0 18px ${color}60`
                                : "none",
                            }}
                          />
                        ))}
                      </div>
                    </Field>
                  </div>
                </div>

                {/* Live preview */}
                <div
                  className="rounded-2xl p-5"
                  style={{
                    background: `linear-gradient(135deg,${form.color}18,${form.color}08)`,
                    border: `1px solid ${form.color}25`,
                  }}
                >
                  <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-3">Live Preview</p>
                  <div className="flex items-center gap-3">
                    <div
                      className="w-10 h-10 rounded-xl flex items-center justify-center text-xl shadow-lg"
                      style={{
                        background: `linear-gradient(135deg,${form.color},${form.color}99)`,
                        boxShadow: `0 6px 20px ${form.color}50`,
                      }}
                    >
                      {form.icon}
                    </div>
                    <div>
                      <p className="font-bold text-white text-sm">{form.name || "Workspace Name"}</p>
                      <p className="text-xs text-slate-500">{memberCount} members</p>
                    </div>
                  </div>
                </div>

                {canEdit && (
                  <button
                    type="submit"
                    disabled={saving}
                    className="btn-primary w-full justify-center py-3"
                  >
                    {saved ? (
                      <><Check size={15} /> Changes saved!</>
                    ) : saving ? (
                      <><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> Saving…</>
                    ) : (
                      <><Settings size={15} /> Save changes</>
                    )}
                  </button>
                )}
              </form>
            </div>
          )}

          {/* ── MEMBERS TAB ─────────────────────────────────── */}
          {activeTab === "members" && (
            <div className="animate-fade-in space-y-6">
              <SectionHeader
                icon={Users}
                title="Members"
                subtitle={`${memberCount} people in this workspace`}
                color="#14b8a6"
              />

              <div
                className="rounded-2xl overflow-hidden"
                style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.06)" }}
              >
                <div className="px-5 py-3.5 border-b flex items-center justify-between" style={{ borderColor: "rgba(255,255,255,0.05)" }}>
                  <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">All members</p>
                  <span
                    className="text-xs font-bold px-2.5 py-1 rounded-full"
                    style={{ background: "rgba(20,184,166,0.12)", color: "#5eead4", border: "1px solid rgba(20,184,166,0.2)" }}
                  >
                    {memberCount}
                  </span>
                </div>

                <div className="divide-y" style={{ borderColor: "rgba(255,255,255,0.04)" }}>
                  {activeWorkspace.members?.map((member, i) => {
                    const meta = ROLE_META[member.role] || ROLE_META.member;
                    const RoleIcon = meta.icon;
                    const isYou = member.user?._id === user?._id;
                    return (
                      <div
                        key={member.user?._id || i}
                        className="flex items-center gap-4 px-5 py-4 transition-all duration-150 group"
                        style={{ animationDelay: `${i * 40}ms` }}
                        onMouseEnter={e => e.currentTarget.style.background = "rgba(255,255,255,0.02)"}
                        onMouseLeave={e => e.currentTarget.style.background = ""}
                      >
                        <div className="relative flex-shrink-0">
                          <Avatar user={member.user} size="sm" online={isYou} />
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-semibold text-white truncate flex items-center gap-2">
                            {member.user?.name || "Unknown"}
                            {isYou && (
                              <span className="text-[10px] font-semibold px-1.5 py-0.5 rounded-full"
                                style={{ background: "rgba(99,102,241,0.15)", color: "#818cf8", border: "1px solid rgba(99,102,241,0.25)" }}>
                                You
                              </span>
                            )}
                          </p>
                          <p className="text-xs text-slate-500 truncate mt-0.5">{member.user?.email}</p>
                        </div>
                        <span
                          className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold flex-shrink-0"
                          style={{ background: meta.bg, color: meta.color, border: `1px solid ${meta.color}30` }}
                        >
                          <RoleIcon size={10} />
                          {meta.label}
                        </span>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          )}

          {/* ── INVITE TAB ──────────────────────────────────── */}
          {activeTab === "invite" && canEdit && (
            <div className="animate-fade-in space-y-6">
              <SectionHeader
                icon={UserPlus}
                title="Invite People"
                subtitle="Send an invite link to add teammates to this workspace."
                color="#f97316"
              />

              <div
                className="rounded-2xl p-6 space-y-5"
                style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.06)" }}
              >
                <form onSubmit={handleInvite} className="space-y-4">
                  <Field label="Email address">
                    <div className="relative">
                      <Mail size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" />
                      <input
                        type="email"
                        value={inviteEmail}
                        onChange={e => setInviteEmail(e.target.value)}
                        placeholder="colleague@company.com"
                        className="input-field pl-10"
                      />
                    </div>
                  </Field>

                  <Field label="Role">
                    <select
                      value={inviteRole}
                      onChange={e => setInviteRole(e.target.value)}
                      className="input-field select-field"
                    >
                      <option value="member">Member — Can view and edit</option>
                      <option value="admin">Admin — Full access</option>
                      <option value="viewer">Viewer — Read only</option>
                    </select>
                  </Field>

                  <button
                    type="submit"
                    disabled={inviting || !inviteEmail}
                    className="btn-primary w-full justify-center py-3"
                    style={{
                      background: "linear-gradient(135deg,#f97316,#ea580c)",
                      boxShadow: "0 4px 20px rgba(249,115,22,0.35)",
                    }}
                  >
                    <UserPlus size={15} />
                    {inviting ? "Sending invite…" : "Send Invite"}
                  </button>
                </form>

                {inviteResult && (
                  <div
                    className="rounded-xl p-4 animate-fade-in"
                    style={inviteResult.success
                      ? { background: "rgba(16,185,129,0.08)", border: "1px solid rgba(16,185,129,0.2)" }
                      : { background: "rgba(239,68,68,0.08)", border: "1px solid rgba(239,68,68,0.2)" }
                    }
                  >
                    {inviteResult.success ? (
                      <div className="space-y-3">
                        <p className="text-sm font-semibold text-emerald-400 flex items-center gap-2">
                          <Check size={14} /> Invite created successfully!
                        </p>
                        <div
                          className="flex items-center gap-2 px-3 py-2.5 rounded-xl"
                          style={{ background: "rgba(0,0,0,0.25)", border: "1px solid rgba(255,255,255,0.06)" }}
                        >
                          <code className="flex-1 text-xs text-slate-300 truncate">
                            {inviteResult.invite?.inviteLink}
                          </code>
                          <button
                            onClick={copyLink}
                            className="p-1.5 rounded-lg transition-all flex-shrink-0"
                            style={{
                              background: copiedLink ? "rgba(16,185,129,0.15)" : "rgba(255,255,255,0.06)",
                              color: copiedLink ? "#34d399" : "#94a3b8",
                            }}
                          >
                            {copiedLink ? <Check size={13} /> : <Copy size={13} />}
                          </button>
                        </div>
                      </div>
                    ) : (
                      <p className="text-sm text-red-400 flex items-center gap-2">
                        <span className="w-1.5 h-1.5 rounded-full bg-red-400 flex-shrink-0" />
                        {inviteResult.message}
                      </p>
                    )}
                  </div>
                )}
              </div>

              {/* Info card */}
              <div
                className="rounded-xl p-4 flex gap-3"
                style={{ background: "rgba(249,115,22,0.06)", border: "1px solid rgba(249,115,22,0.15)" }}
              >
                <Globe size={14} className="text-orange-400 mt-0.5 flex-shrink-0" />
                <p className="text-xs text-slate-500 leading-relaxed">
                  The invite link is unique and will expire after 7 days. You can always generate a new one.
                </p>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default WorkspaceSettings;
